(7197454, 1107463, 97225, '<td valign="top">I love the warm tones and great textures. The grass looks like fur - like a huge animal hide laid over the ground.</td>', 'I love the warm tones and great textures. The grass looks like fur - like a huge animal hide laid over the ground.', '2014-04-02 03:05:30.000000', NULL, 1),
(7197494, 1107520, 114285, '<td valign="top">This looks straight out of camera, with some PP this could of popped.<br/> <br/>Still pretty good job.</td>', 'This looks straight out of camera, with some PP this could of popped. Still pretty good job.', '2014-04-02 06:41:15.000000', NULL, 1),
(7197729, 1107527, 150277, '<td valign="top">Nice.  I found this peaceful and calming.</td>', 'Nice.  I found this peaceful and calming.', '2014-04-02 14:42:38.000000', NULL, 1),
(7197731, 1107476, 150277, '<td valign="top">nice view!  Lighting is a bit underwhelming, but it is a great perspective.</td>', 'nice view!  Lighting is a bit underwhelming, but it is a great perspective.', '2014-04-02 14:44:34.000000', NULL, 1),
