(7198843, 1107283, 173844, '<td valign="top">Very beautiful image that winks back and forth from landscape to abstract.  The distribution of colors and shapes integrate to form an exciting whole.  My favorite in the challenge, and going into my favorites.</td>', 'Very beautiful image that winks back and forth from landscape to abstract.  The distribution of colors and shapes integrate to form an exciting whole.  My favorite in the challenge, and going into my favorites.', '2014-04-04 16:47:54.000000', NULL, 1),
(7198844, 1107463, 173844, '<td valign="top">A wonderful deep image, beautiful in its own right, that is a textural tour de force.  The browns, blues, grays and dark green sing of nature without a hint of pretension.  Formidable.</td>', 'A wonderful deep image, beautiful in its own right, that is a textural tour de force.  The browns, blues, grays and dark green sing of nature without a hint of pretension.  Formidable.', '2014-04-04 16:56:06.000000', NULL, 1),
(7198846, 1107407, 173844, '<td valign="top">Lovely impressionistic scene that works wonders with blur and leading lines.  It''s joyful and full of promise.  Who wouldn''t take this adventure?  I''ll put it in my favorites to gaze at in the winter.</td>', 'Lovely impressionistic scene that works wonders with blur and leading lines.  It''s joyful and full of promise.  Who wouldn''t take this adventure?  I''ll put it in my favorites to gaze at in the winter.', '2014-04-04 17:03:19.000000', NULL, 1),
(7198855, 1107235, 173844, '<td valign="top">Beautiful landscape, fading from black to ethereal, overflown and studied by a bird (hawk?) leisurely exiting the frame.  Terrific tones, grain and composition.  A favorite.</td>', 'Beautiful landscape, fading from black to ethereal, overflown and studied by a bird (hawk?) leisurely exiting the frame.  Terrific tones, grain and composition.  A favorite.', '2014-04-04 17:12:09.000000', NULL, 1),
(7198858, 1107347, 173844, '<td valign="top">All about the lovely light and the dark forest beyond.  Beautifully done.</td>', 'All about the lovely light and the dark forest beyond.  Beautifully done.', '2014-04-04 17:15:02.000000', NULL, 1),
(7198937, 1107283, 94815, '<td valign="top">I like the postprocessing - ott but sensitively done to emphasize the contrast between the snowy and earthy areas. A visual treat. 8</td>', 'I like the postprocessing - ott but sensitively done to emphasize the contrast between the snowy and earthy areas. A visual treat. 8', '2014-04-04 22:28:06.000000', NULL, 1),
(7198938, 1107530, 94815, '<td valign="top">City landscape works for me for its incisive detail.</td>', 'City landscape works for me for its incisive detail.', '2014-04-04 22:29:16.000000', NULL, 1),
(7198940, 1107347, 94815, '<td valign="top">Moody and brilliant. 7</td>', 'Moody and brilliant. 7', '2014-04-04 22:29:38.000000', NULL, 1),
(7198941, 1107391, 94815, '<td valign="top">Foreground well done but this needs deeper dof because the overall detail and dramatically receding effect is lost in the blurred distance. 6 but could have been better.</td>', 'Foreground well done but this needs deeper dof because the overall detail and dramatically receding effect is lost in the blurred distance. 6 but could have been better.', '2014-04-04 22:31:34.000000', NULL, 1),
